 @Test void r1BlockPreviewApplyKeepsIdentityAndMeaningGateThroughRealDbAndRegister()throws Exception{
  long sid=number(session().get("id"));analyze(sid,"メモ: SKP: 田中");var block=blockList(sid).getFirst();String path="/import/session/"+sid+"/unparsed-blocks/"+block.get("id");var b=blockRequest(sid,block,List.of(map("startOffset",4,"endOffset",text(block.get("originalText")).length())));
  var preview=post(path+"/candidate-preview",b);assertEquals(200,preview.status,preview.raw);String previewKey=text(list(obj(list(preview.body.get("parts")).getFirst().get("candidateData")).get("participations")).getFirst().get("candidateParticipationKey"));
  b.put("previewRevision",preview.body.get("previewRevision"));var applied=post(path+"/candidates",b);assertEquals(200,applied.status,applied.raw);long cid=number(((List<?>)applied.body.get("candidateIds")).getFirst());assertTrue(version(sid)>number(b.get("expectedSessionVersion")));assertEquals(previewKey,list(obj(candidate(sid,cid).get("candidateData")).get("participations")).getFirst().get("candidateParticipationKey"));assertActiveIdentity(sid,cid);
  var d=obj(candidate(sid,cid).get("candidateData"));d.put("scenarioName","R1正式保存");var p=list(d.get("participations")).getFirst();p.put("role","KP");p.put("roleMeaningAccepted",false);candidatePatch(sid,cid,map("candidateData",d,"confirmationStatus","CHECKED"));bindSupplement(sid,cid);candidatePatch(sid,cid,map("confirmationStatus","CHECKED"));assertEquals("NEEDS_FIX",candidate(sid,cid).get("status"));int tablesBefore=jdbc.queryForObject("select count(*) from trpg_table",Integer.class);assertEquals("FAILED",list(registerOne(sid,cid).body.get("results")).getFirst().get("outcome"));assertEquals(tablesBefore,jdbc.queryForObject("select count(*) from trpg_table",Integer.class));
  p.put("roleMeaningAccepted",true);candidatePatch(sid,cid,map("candidateData",d,"confirmationStatus","CHECKED"));var registered=list(registerOne(sid,cid).body.get("results")).getFirst();assertEquals("REGISTERED",registered.get("outcome"));assertEquals("KP",list(table(number(registered.get("registeredTableId"))).get("participations")).getFirst().get("role"));
 }
 void assertActiveIdentity(long sid,long cid)throws Exception{
  var detail=get("/import/session/"+sid+"/candidates/"+cid).body;var c=obj(detail.get("candidate"));var keys=new HashSet<>();list(obj(c.get("candidateData")).get("participations")).forEach(p->keys.add(p.get("candidateParticipationKey")));
  for(var r:list(obj(c.get("inference")).get("relations")))if(!"DETACHED".equals(r.get("association")))assertTrue(keys.contains(r.get("candidateParticipationKey")),write(r));
  for(var context:list(detail.get("sourceContexts")))for(var t:list(context.get("traces")))if(!"DETACHED".equals(t.get("association"))&&text(t.get("fieldPath")).startsWith("/participations/"))assertTrue(keys.contains(text(t.get("fieldPath")).split("/")[2]),write(t));
 }
