 @Test void r4ContextConflictSurvivesHttpAndDbInBothColumnOrders()throws Exception{
  long sid=number(session().get("id"));String raw="シナリオ名,記録,記録,氏名,PC\nA,予定,実施済み,田中,青い月\nA,実施済み,予定,佐藤,赤い星";multipart("POST","/import/session/"+sid+"/sources/files","files",List.of(new Upload("context.csv",raw.getBytes(StandardCharsets.UTF_8))),version(sid));post("/import/session/"+sid+"/analyze",map("expectedSessionVersion",version(sid)));var rows=list(get("/import/session/"+sid+"/review").body.get("items"));assertEquals(2,rows.size());for(var row:rows){long cid=number(row.get("candidateId"));var c=candidate(sid,cid);assertNull(list(obj(c.get("candidateData")).get("participations")).getFirst().get("role"));assertTrue(list(obj(c.get("inference")).get("conflicts")).stream().anyMatch(x->"C3".equals(x.get("kind"))));bindSupplement(sid,cid);candidatePatch(sid,cid,map("confirmationStatus","CHECKED"));assertEquals("FAILED",list(registerOne(sid,cid).body.get("results")).getFirst().get("outcome"));}assertEquals(0,jdbc.queryForObject("select count(*) from scenario where name='A'",Integer.class));
 }
