 @LocalServerPort int port;@Autowired JdbcTemplate jdbc;HttpClient client;CookieManager cookies;String token;
 record Result(int status,Map<String,Object> body,String raw,HttpResponse<String> response){}
 @BeforeEach void setup()throws Exception{jdbc.execute("TRUNCATE app_user CASCADE");jdbc.execute("TRUNCATE storage_delete_task RESTART IDENTITY");jdbc.execute("TRUNCATE spring_session CASCADE");for(String table:List.of("app_user","person","scenario","pc","trpg_table","table_date","participation","end_pc_state","pc_system_setting","scenario_favorite","import_session","import_source","import_candidate","import_resolution","import_candidate_source_trace","storage_delete_task","import_preview"))jdbc.execute("ALTER SEQUENCE "+table+"_id_seq RESTART WITH 1");new ResourceDatabasePopulator(new ClassPathResource("db/dev/V1000__local_test_fixtures.sql")).execute(Objects.requireNonNull(jdbc.getDataSource()));cookies=new CookieManager(null,CookiePolicy.ACCEPT_ALL);client=HttpClient.newBuilder().cookieHandler(cookies).build();csrf();Result login=request("POST","/dev/session",null,true);assertEquals(200,login.status,login.raw);csrf();}
 void csrf()throws Exception{token=text(request("GET","/csrf",null,false).body.get("token"));}
 Result request(String method,String path,Object body,boolean csrf)throws Exception{var b=HttpRequest.newBuilder(URI.create("http://127.0.0.1:"+port+"/api"+path));if(csrf)b.header("X-CSRF-TOKEN",token);if(body!=null)b.header("Content-Type","application/json");b.method(method,body==null?HttpRequest.BodyPublishers.noBody():HttpRequest.BodyPublishers.ofString(write(body)));var res=client.send(b.build(),HttpResponse.BodyHandlers.ofString());Map<String,Object> json;try{json=object(res.body());}catch(Exception e){json=map();}return new Result(res.statusCode(),json,res.body(),res);}
 Result get(String path)throws Exception{return request("GET",path,null,false);}Result post(String path,Object b)throws Exception{return request("POST",path,b,true);}Result patch(String path,Object b)throws Exception{return request("PATCH",path,b,true);}
 long number(Object v){return ((Number)v).longValue();}Map<String,Object> table(long id)throws Exception{return get("/tables/"+id).body;}
 void code(Result r,int status,String code){assertEquals(status,r.status,r.raw);assertEquals(code,r.body.get("code"),r.raw);assertTrue(r.body.containsKey("fieldErrors"));}
 Map<String,Object> draft(String name){return map("scenarioName",name,"gameSystemName",null,"tableName",null,"recordingUrl",null,"tableDates",List.of(),"participations",List.of(),"unassignedValues",List.of());}
 Map<String,Object> session()throws Exception{return post("/import/session",null).body;}long version(long sid)throws Exception{return number(get("/import/session/"+sid).body.get("version"));}
 List<Map<String,Object>> analyze(long sid,String text)throws Exception{assertEquals(201,post("/import/session/"+sid+"/sources/text",map("expectedSessionVersion",version(sid),"text",text)).status);assertEquals(200,post("/import/session/"+sid+"/analyze",map("expectedSessionVersion",version(sid))).status);return list(get("/import/session/"+sid+"/review?size=100").body.get("items"));}
 Map<String,Object> candidate(long sid,long cid)throws Exception{return obj(get("/import/session/"+sid+"/candidates/"+cid).body.get("candidate"));}
 Result candidatePatch(long sid,long cid,Map<String,Object>b)throws Exception{var body=new LinkedHashMap<>(b);body.put("expectedSessionVersion",version(sid));body.put("expectedVersion",candidate(sid,cid).get("version"));return patch("/import/session/"+sid+"/candidates/"+cid,body);}
